sp_widget.client_script:
/*
  CLM – Approval Requests (TSH / TSM / TSH_BPD) – Trade – Client Script  v2.5-TSH
  - Business options come from the server (CLMBusinessAccess, persona TSH)
  - Picking another business (Non-Trade / Key) reverts the dropdown and broadcasts
    'clm.business.changed' with the dashboard key (trade / nonTrade / key)
*/
function widgetcontroller($scope, $rootScope, $timeout) {
  var c = this;

  var DEFAULT_BUSINESS = 'trade';
  var HOST_KEY = { trade: 'trade', non_trade: 'nonTrade', key: 'key' };
  var FALLBACK_BUSINESS_OPTIONS = [{ value: 'trade', label: 'Trade', enabled: true }];

  c.filters = {
    business: c.data.selectedBusiness || DEFAULT_BUSINESS,
    segments: [],
    depots: [],
    status: '',
    period: c.data.selectedPeriod || 'latest',
    search: ''
  };

  c.rowsPerPageOptions = [10, 15, 20, 50, 100];
  c.pagination = { currentPage: 1, rowsPerPage: 10 };
  c.hoverIndex = -1;
  c.showTooltip = false;
  c.paginatedRequests = [];
  c.kpiFilter = '';
  c.kpiLabels = { pending: 'Pending', approved: 'Approved', rejected: 'Rejected', deviated: 'Deviated' };

  c.seriesDefs = [
    { key: 'submitted', label: 'Pending' },
    { key: 'approved',  label: 'Approved' },
    { key: 'rejected',  label: 'Rejected' },
    { key: 'total',     label: 'Total' }
  ];

c.depotDropdownOpen = false;
c.segmentDropdownOpen = false;
c.depotSearch = '';
c.closeAllDropdowns = function() { c.depotDropdownOpen = false; c.segmentDropdownOpen = false; };

  // ===================== BUSINESS =====================
  c.getBusinessOptions = function() {
      return (c.data && c.data.businessOptions && c.data.businessOptions.length) ? c.data.businessOptions : FALLBACK_BUSINESS_OPTIONS;
  };
  c.isBusinessEnabled = function(value) {
      return c.getBusinessOptions().some(function(b) { return b.value === value && b.enabled; });
  };
  c._lastBusiness = c.filters.business;

  c.onBusinessChange = function() {
      var value = c.filters.business;
      if (!c.isBusinessEnabled(value)) { c.filters.business = c._lastBusiness || DEFAULT_BUSINESS; return; }
      if (value === c._lastBusiness) return;

      if (value !== DEFAULT_BUSINESS) {
          c.filters.business = c._lastBusiness;
          $rootScope.$broadcast('clm.business.changed', { business: HOST_KEY[value] || value, from: 'trade' });
          return;
      }
      c._lastBusiness = value;
     c.filters.segments = []; c.filters.depots = []; c.filters.status = ''; c.filters.search = ''; c.kpiFilter = '';
      c.depotSearch = '';
      c.closeAllDropdowns();
      c.applyFilters();
  };

  // ===================== SEGMENT =====================
// ===================== SEGMENT multiselect (empty selection = All Segments) =====================
c.getSegmentOptions = function() {
    return (c.data && c.data.filterOpts && c.data.filterOpts.segments) || [];
};
c.hasSegmentSelection = function() { return c.filters.segments.length > 0; };
c.openSegmentDropdown = function() { c.closeAllDropdowns(); c.segmentDropdownOpen = true; };
c.closeSegmentDropdown = function() { c.segmentDropdownOpen = false; };
c.isSegmentSelected = function(s) { return c.filters.segments.indexOf(s) !== -1; };
c.toggleSegment = function(s) {
    var idx = c.filters.segments.indexOf(s);
    if (idx === -1) c.filters.segments.push(s); else c.filters.segments.splice(idx, 1);
    c.applyFilters();
};
c.selectAllSegments = function() {
    c.filters.segments = c.getSegmentOptions().slice();
    c.applyFilters();
};
c.clearAllSegments = function() {
    c.filters.segments = [];
    c.applyFilters();
};
c.getSegmentDisplayText = function() {
    var n = c.filters.segments.length;
    if (!n) return 'All Segments';
    if (n === 1) return c.filters.segments[0];
    return n + ' segments selected';
};

  // ===================== DEPOT multiselect =====================
  function allDepotOpts() { return (c.data && c.data.filterOpts && c.data.filterOpts.depots) || []; }

  c.openDepotDropdown = function() { c.closeAllDropdowns(); c.depotDropdownOpen = true; };
  c.closeDepotDropdown = function() { c.depotDropdownOpen = false; };
  c.toggleDepot = function(d) {
      var idx = c.filters.depots.indexOf(d.value);
      if (idx === -1) c.filters.depots.push(d.value); else c.filters.depots.splice(idx, 1);
      c.depotSearch = ''; c.applyFilters();
  };
  c.selectAllDepots = function() { c.filters.depots = allDepotOpts().map(function(d) { return d.value; }); c.depotSearch = ''; c.applyFilters(); };
  c.clearAllDepots = function() { c.filters.depots = []; c.depotSearch = ''; c.applyFilters(); };
  c.isDepotSelected = function(d) { return c.filters.depots.indexOf(d.value) !== -1; };
  c.getFilteredDepots = function() {
      var all = allDepotOpts(), term = (c.depotSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(d) {
          return String(d.label || '').toLowerCase().indexOf(term) !== -1 || String(d.value || '').toLowerCase().indexOf(term) !== -1;
      });
  };
  c.getDepotLabel = function(val) {
      var m = allDepotOpts().filter(function(d) { return d.value === val; })[0];
      return m ? m.label : val;
  };
  c.getDepotDisplayText = function() {
      if (!c.filters.depots.length) return 'All Depots';
      if (c.filters.depots.length === 1) return c.getDepotLabel(c.filters.depots[0]);
      return c.filters.depots.length + ' depots selected';
  };

  // ===================== ZONE / REGION (read-only, from Depot) =====================
  var GEO_PLACEHOLDER = 'Auto – based on Depot';
  function fmtGeo(name, code) {
      name = (name || '').toString().trim(); code = (code || '').toString().trim();
      if (name && code && name !== code) return name + ' (' + code + ')';
      return name || code || '';
  }
  function getSelectedGeoList(kind) {
      var opts = allDepotOpts(), seen = {}, out = [];
      (c.filters.depots || []).forEach(function(dv) {
          for (var i = 0; i < opts.length; i++) {
              if (opts[i].value === dv) {
                  var txt = kind === 'zone' ? fmtGeo(opts[i].zoneName, opts[i].zoneCode) : fmtGeo(opts[i].regionName, opts[i].regionCode);
                  if (txt && !seen[txt]) { seen[txt] = true; out.push(txt); }
                  break;
              }
          }
      });
      return out;
  }
  c.hasDepotSelection = function() { return !!(c.filters.depots && c.filters.depots.length > 0); };
  function geoText(kind) {
      if (!c.hasDepotSelection()) return GEO_PLACEHOLDER;
      var list = getSelectedGeoList(kind);
      return list.length ? list.join(', ') : '—';
  }
  c.getZoneDisplayText   = function() { return geoText('zone'); };
  c.getRegionDisplayText = function() { return geoText('region'); };
  c.getZoneTooltip       = function() { return c.hasDepotSelection() ? getSelectedGeoList('zone').join(', ') : ''; };
  c.getRegionTooltip     = function() { return c.hasDepotSelection() ? getSelectedGeoList('region').join(', ') : ''; };

  // ===================== Filter helpers =====================
c.hasActiveFilters = function() {
    var f = c.filters;
    return !!(f.segments.length || f.depots.length || f.status || (f.period && f.period !== 'latest'));
};
c.clearAllFilters = function() {
    c.filters.segments = [];
    c.filters.depots = []; c.filters.status = ''; c.filters.period = 'latest';
    c.closeAllDropdowns();
    c.applyFilters();
};

  c.openRequestDetail = function(r) {
      if (!r || !r.requestCode) return;
      var biz = HOST_KEY[c.filters.business] || c.filters.business;
      $rootScope.clmPendingRequestNumber = r.requestCode;
      $rootScope.clmPendingRequestBusiness = biz;
      $rootScope.$broadcast('clm.request.selected', { number: r.requestCode, business: biz });
      $rootScope.$broadcast('clm.switch.tab', 'request_detail');
  };

  c.applyFilters = function() {
    c.pagination.currentPage = 1;
c.data.filters = {
  business: c.filters.business,
  segments: c.filters.segments,                                            // new: array, [] = all
  segment: c.filters.segments.length === 1 ? c.filters.segments[0] : '',   // back-compat for old server code
  depots: c.filters.depots,
  status: c.filters.status, period: c.filters.period
};
    c.server.update().then(function() {
      if (c.data.selectedBusiness) c.filters.business = c._lastBusiness = c.data.selectedBusiness;
      var validSeg = c.getSegmentOptions();
c.filters.segments = c.filters.segments.filter(function(s) { return validSeg.indexOf(s) !== -1; });
      if (c.data.selectedPeriod)   c.filters.period   = c.data.selectedPeriod;
      var valid = allDepotOpts().map(function(d) { return d.value; });
      c.filters.depots = c.filters.depots.filter(function(v) { return valid.indexOf(v) !== -1; });
      c.buildChartScale();
      c.onMouseLeaveChart();
      c.runSearch();
    });
  };

  c.scrollToTable = function() {
      $timeout(function() {
          var el = document.getElementById('clmRequestsTableContainer');
          if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
  };

  c.setKpiFilter = function(state) {
      state = state || '';
      if (!state) { c.kpiFilter = ''; c.scrollToTable(); }
      else if (c.kpiFilter === state) { c.kpiFilter = ''; }
      else { c.kpiFilter = state; c.scrollToTable(); }
      c.pagination.currentPage = 1;
      c.runSearch();
  };

  c.runSearch = function() {
    var term = (c.filters.search || '').toString().toLowerCase().trim();
    (c.data.requests || []).forEach(function(r) {
      var isHidden = false;
      if (term) {
        var fields = [r.requestCode, r.customerCode, r.customerName, r.pan,
                      r.zone, r.zoneName, r.zoneCode, r.region, r.regionName, r.regionCode,
                      r.depot, r.depotName, r.depotCode];
        if (!fields.some(function(f) { return (f || '').toString().toLowerCase().indexOf(term) > -1; })) isHidden = true;
      }
      if (!isHidden && c.kpiFilter) {
          if (c.kpiFilter === 'deviated') { if (!r.isDeviation) isHidden = true; }
          else {
              var statLower = (r.status || '').toLowerCase();
              if (c.kpiFilter === 'pending' && statLower.indexOf('submit') === -1) isHidden = true;
              if (c.kpiFilter === 'approved' && statLower.indexOf('approv') === -1) isHidden = true;
              if (c.kpiFilter === 'rejected' && statLower.indexOf('reject') === -1) isHidden = true;
          }
      }
      r._hidden = isHidden;
    });
    c.pagination.currentPage = 1;
    c.updatePaginatedRequests();
  };

  c.updatePaginatedRequests = function() {
    var visible = (c.data.requests || []).filter(function(r) { return !r._hidden; });
    var start = (c.pagination.currentPage - 1) * c.pagination.rowsPerPage;
    c.paginatedRequests = visible.slice(start, start + c.pagination.rowsPerPage);
  };
  c.getVisibleRecordsCount = function() { return (c.data.requests || []).filter(function(r) { return !r._hidden; }).length; };
  c.getTotalPages = function() { return Math.ceil(c.getVisibleRecordsCount() / c.pagination.rowsPerPage) || 1; };
  c.getPageNumbers = function() {
    var total = c.getTotalPages(), pages = [], maxVisible = 5;
    var start = Math.max(1, c.pagination.currentPage - Math.floor(maxVisible / 2));
    var end = Math.min(total, start + maxVisible - 1);
    if (end - start < maxVisible - 1) start = Math.max(1, end - maxVisible + 1);
    for (var i = start; i <= end; i++) pages.push(i);
    return pages;
  };
  c.previousPage = function() { if (c.pagination.currentPage > 1) { c.pagination.currentPage--; c.updatePaginatedRequests(); } };
  c.nextPage = function() { if (c.pagination.currentPage < c.getTotalPages()) { c.pagination.currentPage++; c.updatePaginatedRequests(); } };
  c.goToPage = function(p) { c.pagination.currentPage = p; c.updatePaginatedRequests(); };
  c.onRowsPerPageChange = function() { c.pagination.currentPage = 1; c.updatePaginatedRequests(); };

  $scope.$watch('c.filters.search', c.runSearch);

  // ===================== Chart =====================
  var PLOT_W = 1000, PLOT_H = 200;
  c.chartScale = { top: 4, ticks: [0, 1, 2, 3, 4] };
  c.buildChartScale = function() {
    var max = (c.data.chart && c.data.chart.max) || 0;
    var step, top;
    if (max <= 4) { step = 1; top = 4; }
    else {
      var raw = max / 4, mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), r = raw / mag;
      step = (r <= 1 ? 1 : r <= 2 ? 2 : r <= 2.5 ? 2.5 : r <= 5 ? 5 : 10) * mag;
      if (step < 1) step = 1;
      top = step * Math.ceil(max / step);
    }
    var ticks = [];
    for (var v = 0; v <= top + 1e-9; v += step) ticks.push(Math.round(v * 100) / 100);
    c.chartScale = { top: top, ticks: ticks };
  };
  function monthCount() { return ((c.data.chart && c.data.chart.months) || []).length; }
  c.chartX = function(i) { var n = monthCount(); return n <= 1 ? PLOT_W / 2 : i * (PLOT_W / (n - 1)); };
  c.chartY = function(v) { return PLOT_H - ((v || 0) / (c.chartScale.top || 1)) * PLOT_H; };
  c.xPct = function(i) { return c.chartX(i) / PLOT_W * 100; };
  c.yPct = function(v) { return c.chartY(v) / PLOT_H * 100; };
  c.colWidth = function() { var n = monthCount(); return n <= 1 ? PLOT_W : PLOT_W / (n - 1); };
  c.linePoints = function(key) {
    var months = (c.data.chart && c.data.chart.months) || [];
    var s = ((c.data.chart && c.data.chart.series) || {})[key] || [];
    return months.map(function(m, i) { return c.chartX(i) + ',' + c.chartY(s[i] || 0); }).join(' ');
  };
  c.onMouseOverMonth = function(ev, index) { c.hoverIndex = index; c.showTooltip = true; };
  c.onMouseLeaveChart = function() { c.hoverIndex = -1; c.showTooltip = false; };

  // ===================== Badges =====================
  c.statusClass = function(status) {
    var s = (status || '').toLowerCase();
    if (s.indexOf('submit') > -1 || s.indexOf('pend') > -1) return 'st-submitted';
    if (s.indexOf('approv') > -1) return 'st-approved';
    if (s.indexOf('return') > -1 || s.indexOf('send') > -1) return 'st-sendback';
    if (s.indexOf('reject') > -1) return 'st-rejected';
    return 'st-default';
  };
  c.segClass = function(seg) {
    var s = (seg || '').toLowerCase();
    if (s.indexOf('cement') > -1) return 'seg-cement';
    if (s.indexOf('rmc') > -1) return 'seg-rmc';
    if (s.indexOf('bpd') > -1) return 'seg-bpd';
    return 'seg-default';
  };

  c.buildChartScale();
  c.updatePaginatedRequests();
}

sp_widget.css:
/*
  CLM – Approval Requests (TSH / TSM / TSH_BPD dashboard)  v2.3-TSH
  Same as MD master v2.3, plus a "TSH overrides" block: read-only Zone / Region boxes,
  the depot option code style and slightly tighter table cells so the 12 columns fit at 1366px.
  v2.3-TSH (aligned to master v2.2 / v2.3)
  - Filter row: 7 equal columns (Business, Segment, Zone, Region, Depot, Status, Period);
    4 per row under 1280px, 2 under 768px, 1 under 640px (was 6 / 3 / – / 1)
  - Business dropdown: disabled options (Non-Trade / Key) greyed (.clm-ar-biz-select option:disabled)
*/
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

.clm-ar {
  color: #1a1a1a;
  font-size: 13px;
  padding: 20px;
  background: #f4f5f7;
}

/* ===================== Card (block) ===================== */
.clm-ar .clm-block { margin: 0 0 16px; background: #fff; border: 1px solid #dde3ea; border-radius: 8px; }
.clm-ar .clm-block-head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap;
  padding: 14px 20px; background: #fafbfc; border-bottom: 1px solid #dde3ea; border-radius: 8px 8px 0 0;
}
.clm-ar .clm-block-title {
  display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 700; color: #1a1a1a;
  text-transform: uppercase; letter-spacing: .8px;
}
.clm-ar .clm-block-title::before { content: ""; width: 4px; height: 16px; border-radius: 2px; background: #F3D54E; flex-shrink: 0; }
.clm-ar .clm-block-sub { margin: 4px 0 0 14px; font-size: 12px; color: #5a6a7a; }
.clm-ar .clm-block-meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.clm-ar .clm-chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; background: #fff;
  border: 1px solid #dde3ea; border-radius: 12px; font-size: 12px; font-weight: 700; color: #1a1a1a; white-space: nowrap;
}
.clm-ar .clm-chip-k { font-weight: 400; color: #5a6a7a; }
.clm-ar .clm-tw-body { padding: 18px 20px; }
.clm-ar .clm-no-data { text-align: center; color: #7f8c9a; padding: 24px 0; font-style: italic; }

.clm-ar .clm-ar-clear {
  padding: 4px 12px; background: #fff; border: 1px solid #cdd4dc; border-radius: 12px;
  font-size: 12px; font-weight: 700; color: #3a4451; cursor: pointer;
}
.clm-ar .clm-ar-clear:hover { background: #1a1a1a; border-color: #1a1a1a; color: #F3D54E; }

/* ===================== Filters ===================== */
.clm-ar .clm-ar-filters .clm-tw-body { padding: 16px 20px; }
.clm-ar .clm-filter-row { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 14px; }
.clm-ar .clm-filter-field {
  display: flex; flex-direction: column; gap: 6px; margin: 0; min-width: 0; position: relative; font-weight: 400;
}
.clm-ar .clm-filter-k { font-size: 12px; font-weight: 700; color: #3a4451; text-transform: uppercase; letter-spacing: .6px; }
.clm-ar .clm-filter-field select {
  width: 100%; height: 36px; font-size: 13px; color: #1a1a1a; border-radius: 6px; border: 1px solid #cdd4dc;
  background-color: #fff; padding: 0 10px; outline: none; cursor: pointer; box-shadow: none; box-sizing: border-box;
}
.clm-ar .clm-filter-field select:hover { border-color: #a0aab6; }
.clm-ar .clm-filter-field select:focus { border-color: #1a1a1a; box-shadow: 0 0 0 2px rgba(243, 213, 78, .45); }

/* ---------- Business dropdown: disabled options (Non-Trade / Key) ---------- */
.clm-ar .clm-ar-biz-select option:disabled { color: #b0b9c4; }

/* ---------- Read-only boxes (Zone / Region) ---------- */
.clm-ar .clm-readonly-box {
  display: flex; align-items: center; width: 100%; height: 36px; padding: 0 10px; box-sizing: border-box; font-size: 13px;
  border: 1px dashed #cdd4dc; border-radius: 6px; background: #f6f7f9; color: #1a1a1a; cursor: not-allowed; user-select: none; overflow: hidden;
}
.clm-ar .clm-readonly-box.clm-readonly-empty { color: #7f8c9a; font-style: italic; }
.clm-ar .clm-ro-lock { margin-left: 4px; font-size: 10px; color: #9aa5b1; }

/* ---------- Multiselect ---------- */
.clm-ar .clm-multiselect-container { position: relative; width: 100%; }
.clm-ar .clm-multiselect-trigger {
  display: flex; align-items: center; justify-content: space-between; width: 100%; height: 36px; padding: 0 10px;
  font-size: 13px; border: 1px solid #cdd4dc; border-radius: 6px; background: #fff; cursor: pointer; box-sizing: border-box;
}
.clm-ar .clm-multiselect-trigger:hover { border-color: #a0aab6; }
.clm-ar .clm-multiselect-container.open .clm-multiselect-trigger {
  border-color: #1a1a1a; border-bottom-left-radius: 0; border-bottom-right-radius: 0;
}
.clm-ar .clm-multiselect-text { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #1a1a1a; }
.clm-ar .clm-multiselect-arrow { color: #7f8c9a; font-size: 10px; margin-left: 6px; }
.clm-ar .clm-multiselect-dropdown {
  position: absolute; top: 36px; left: 0; right: 0; min-width: 220px; z-index: 60; background: #fff;
  border: 1px solid #1a1a1a; border-top: none; border-radius: 0 0 6px 6px; box-shadow: 0 8px 18px rgba(0, 0, 0, .12);
  max-height: 300px; display: flex; flex-direction: column; overflow: hidden;
}
.clm-ar .clm-multiselect-actions {
  display: flex; justify-content: space-between; padding: 7px 12px; border-bottom: 1px solid #e6eaef; background: #fafbfc;
}
.clm-ar .clm-multiselect-actions a { font-size: 12px; font-weight: 700; color: #3a4451; cursor: pointer; }
.clm-ar .clm-multiselect-actions a:hover { text-decoration: underline; }
.clm-ar .clm-multiselect-search {
  width: 100%; height: 34px; padding: 0 12px; border: none; border-bottom: 1px solid #e6eaef;
  font-size: 12.5px; outline: none; box-sizing: border-box;
}
.clm-ar .clm-multiselect-list { list-style: none; margin: 0; padding: 4px 0; overflow-y: auto; max-height: 190px; }
.clm-ar .clm-multiselect-list li {
  display: flex; align-items: center; gap: 8px; padding: 7px 12px; font-size: 13px; color: #1a1a1a; cursor: pointer;
}
.clm-ar .clm-multiselect-list li:hover { background: #f4f5f7; }
.clm-ar .clm-multiselect-list li.selected { background: #fffcf0; font-weight: 700; }
.clm-ar .clm-checkbox {
  width: 14px; height: 14px; border: 2px solid #cdd4dc; border-radius: 3px; display: inline-block; flex-shrink: 0; position: relative;
}
.clm-ar .clm-checkbox.checked { background: #1a1a1a; border-color: #1a1a1a; }
.clm-ar .clm-checkbox.checked::after {
  content: ''; position: absolute; left: 3px; top: 0; width: 4px; height: 8px;
  border: solid #F3D54E; border-width: 0 2px 2px 0; transform: rotate(45deg);
}
.clm-ar .clm-dropdown-empty { color: #7f8c9a !important; cursor: default !important; font-style: italic; }
.clm-ar .clm-dropdown-empty:hover { background: #fff !important; }

/* ===================== Status tiles ===================== */
.clm-ar .clm-ar-stats { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin: 0 0 16px; }
.clm-ar .clm-ar-stat {
  display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 14px 16px; background: #fff;
  border: 1px solid #dde3ea; border-top: 4px solid #cdd4dc; border-radius: 8px; cursor: pointer; text-align: left;
  transition: box-shadow .2s, background-color .2s; outline: none;
}
.clm-ar .clm-ar-stat:hover { box-shadow: 0 3px 10px rgba(0, 0, 0, .06); }
.clm-ar .clm-ar-stat-k { font-size: 12px; font-weight: 700; color: #3a4451; text-transform: uppercase; letter-spacing: .6px; }
.clm-ar .clm-ar-stat-v { font-size: 26px; font-weight: 700; line-height: 1.1; }
.clm-ar .clm-ar-stat-s { font-size: 11px; color: #7f8c9a; }
.clm-ar .clm-ar-stat.st-total     { border-top-color: #1a1a1a; } .clm-ar .st-total    .clm-ar-stat-v { color: #1a1a1a; }
.clm-ar .clm-ar-stat.st-pending   { border-top-color: #2e86c1; } .clm-ar .st-pending  .clm-ar-stat-v { color: #2e86c1; }
.clm-ar .clm-ar-stat.st-approved  { border-top-color: #27ae60; } .clm-ar .st-approved .clm-ar-stat-v { color: #27ae60; }
.clm-ar .clm-ar-stat.st-rejected  { border-top-color: #E23D28; } .clm-ar .st-rejected .clm-ar-stat-v { color: #E23D28; }
.clm-ar .clm-ar-stat.st-deviated  { border-top-color: #E87722; } .clm-ar .st-deviated .clm-ar-stat-v { color: #E87722; }
.clm-ar .clm-ar-stat.is-active {
  background: #fffcf0; border-color: #F3D54E; box-shadow: 0 0 0 2px rgba(243, 213, 78, .35);
}
.clm-ar .clm-ar-stat.is-active.st-total    { border-top-color: #1a1a1a; }
.clm-ar .clm-ar-stat.is-active.st-pending  { border-top-color: #2e86c1; }
.clm-ar .clm-ar-stat.is-active.st-approved { border-top-color: #27ae60; }
.clm-ar .clm-ar-stat.is-active.st-rejected { border-top-color: #E23D28; }
.clm-ar .clm-ar-stat.is-active.st-deviated { border-top-color: #E87722; }

/* ===================== Chart ===================== */
/* series colours: Total charcoal, Pending blue, Approved green, Rejected red */
.clm-ar .k-total     { --k: #1a1a1a; }
.clm-ar .k-submitted { --k: #2e86c1; }
.clm-ar .k-approved  { --k: #27ae60; }
.clm-ar .k-rejected  { --k: #E23D28; }

.clm-ar .clm-ar-legend { gap: 6px 14px; }
.clm-ar .clm-ar-leg { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; color: #3a4451; }
.clm-ar .clm-ar-sw { width: 10px; height: 10px; border-radius: 2px; display: inline-block; background: var(--k); flex-shrink: 0; }

.clm-ar .clm-ar-chart-body { padding: 8px 28px 30px 40px; }
.clm-ar .clm-ar-plot { position: relative; height: 240px; }
.clm-ar .clm-ar-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; display: block; }
.clm-ar .clm-ar-svg line, .clm-ar .clm-ar-svg polyline { vector-effect: non-scaling-stroke; }
.clm-ar .clm-ar-grid { stroke: #eef1f5; stroke-width: 1; }
.clm-ar .clm-ar-grid.is-base { stroke: #c9d1db; }
.clm-ar .clm-ar-guide { stroke: #8a96a3; stroke-width: 1; stroke-dasharray: 4 4; }
.clm-ar .clm-ar-line { fill: none; stroke: var(--k); stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
.clm-ar .clm-ar-line.k-total { stroke-width: 2; stroke-dasharray: 6 5; }
.clm-ar .clm-ar-hit { fill: transparent; cursor: crosshair; }

.clm-ar .clm-ar-ytick {
  position: absolute; right: calc(100% + 10px); transform: translateY(-50%);
  font-size: 11.5px; color: #7f8c9a; font-variant-numeric: tabular-nums; pointer-events: none;
}
.clm-ar .clm-ar-xtick {
  position: absolute; top: calc(100% + 10px); transform: translateX(-50%); white-space: nowrap;
  font-size: 11.5px; color: #5a6a7a; pointer-events: none;
}
.clm-ar .clm-ar-xtick.is-current, .clm-ar .clm-ar-xtick.is-hover { color: #1a1a1a; font-weight: 700; }
.clm-ar .clm-ar-mtd {
  margin-left: 4px; padding: 0 5px; border-radius: 8px; background: #fff8e1; border: 1px solid #F3D54E;
  font-size: 9.5px; font-weight: 700; color: #7a5a00; vertical-align: 1px;
}
.clm-ar .clm-ar-pt {
  position: absolute; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 50%;
  background: #fff; border: 2.5px solid var(--k); box-sizing: border-box; pointer-events: none;
}

.clm-ar .clm-ar-tip {
  position: absolute; top: 0; transform: translateX(14px); z-index: 20; min-width: 170px;
  padding: 10px 12px; background: #1a1a1a; color: #fff; border-radius: 6px;
  box-shadow: 0 6px 16px rgba(0, 0, 0, .2); pointer-events: none; font-size: 12px;
}
.clm-ar .clm-ar-tip.is-flip { transform: translateX(calc(-100% - 14px)); }
.clm-ar .clm-ar-tip .k-total { --k: #ffffff; }
.clm-ar .clm-ar-tip-t {
  margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(255, 255, 255, .18);
  font-weight: 700; color: #F3D54E;
}
.clm-ar .clm-ar-tip-r { display: flex; align-items: center; gap: 8px; margin: 4px 0; }
.clm-ar .clm-ar-tip-k { flex: 1; color: #d6dbe1; }
.clm-ar .clm-ar-tip-v { font-weight: 700; font-variant-numeric: tabular-nums; }

/* ===================== Requests table ===================== */
.clm-ar .clm-ar-toolbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 14px 20px;
}
.clm-ar .clm-search-box { position: relative; display: flex; align-items: center; width: 420px; max-width: 100%; }
.clm-ar .clm-search-box i { position: absolute; left: 12px; color: #7f8c9a; font-size: 13px; }
.clm-ar .clm-search-box input {
  width: 100%; height: 36px; border: 1px solid #cdd4dc; border-radius: 6px; padding: 0 10px 0 34px;
  font-size: 13px; color: #1a1a1a; outline: none; box-sizing: border-box;
}
.clm-ar .clm-search-box input:focus { border-color: #1a1a1a; box-shadow: 0 0 0 2px rgba(243, 213, 78, .45); }
.clm-ar .clm-search-box input::placeholder { color: #7f8c9a; }
.clm-ar .clm-rows-label {
  display: flex; align-items: center; gap: 8px; margin: 0; font-size: 12px; font-weight: 700;
  color: #3a4451; text-transform: uppercase; letter-spacing: .6px;
}
.clm-ar .clm-rows-select {
  height: 34px; padding: 0 8px; min-width: 64px; font-size: 13px; color: #1a1a1a; border: 1px solid #cdd4dc;
  border-radius: 6px; background: #fff; cursor: pointer; outline: none;
}
.clm-ar .clm-ar-kpi-chip { cursor: pointer; background: #fffcf0; border-color: #F3D54E; }
.clm-ar .clm-ar-kpi-chip .clm-ar-x { color: #5a6a7a; font-size: 11px; }
.clm-ar .clm-ar-kpi-chip:hover .clm-ar-x { color: #1a1a1a; }

.clm-ar .clm-table-wrap {
  overflow: auto; max-height: 520px; border-top: 1px solid #dde3ea; border-bottom: 1px solid #dde3ea; background: #fff;
}
.clm-ar .clm-table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; margin: 0; }
.clm-ar .clm-table th {
  background: #eef1f5; color: #2b3440; padding: 10px; font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .6px; text-align: center; white-space: nowrap;
  border: 0; border-bottom: 1px solid #dde3ea;
}
.clm-ar .clm-table thead { position: sticky; top: 0; z-index: 3; }
.clm-ar .clm-table td {
  padding: 10px; color: #1a1a1a; text-align: center; white-space: nowrap; border: 0; border-bottom: 1px solid #e6eaef; vertical-align: middle;
}
.clm-ar .clm-table tr > :first-child { padding-left: 20px; }
.clm-ar .clm-table tr > :last-child  { padding-right: 20px; }
.clm-ar .clm-table tbody tr:last-child td  { border-bottom: 0; }
.clm-ar .clm-table tbody tr:hover td { background: #fafbfc; }

.clm-ar .clm-ar-table td:nth-child(1), .clm-ar .clm-ar-table td:nth-child(2),
.clm-ar .clm-ar-table thead tr:last-child th:nth-child(1),
.clm-ar .clm-ar-table thead tr:last-child th:nth-child(2) { text-align: left; }
.clm-ar .clm-ar-table td.col-customer { white-space: normal; min-width: 150px; max-width: 210px; }
.clm-ar .clm-ar-table td.col-wrap { white-space: normal; min-width: 90px; }
.clm-ar .clm-ar-table td.num { text-align: right; }
.clm-ar .clm-ar-table td.num-key { font-weight: 700; }
.clm-ar .clm-ar-table td.col-submitted-by { text-align: left; white-space: normal; min-width: 150px; }
.clm-ar .clm-ar-table td.col-submitted-by::before { content: none; }
.clm-ar .clm-ar-mono { letter-spacing: .3px; }
.clm-ar .clm-ar-faint { color: #b0b9c4; }
.clm-ar .clm-ar-by { white-space: nowrap; }
.clm-ar .clm-ar-on { margin-top: 2px; font-size: 11px; color: #7f8c9a; }

.clm-ar .clm-link { color: #0b5394; font-weight: 700; text-decoration: none; }
.clm-ar .clm-link:hover { text-decoration: underline; }
.clm-ar .clm-cust-name { font-weight: 700; color: #1a1a1a; }
.clm-ar .clm-cust-code { margin-top: 2px; font-size: 12px; font-weight: 600; color: #5a6a7a; }

/* badges */
.clm-ar .badge {
  display: inline-block; padding: 3px 10px; border-radius: 12px; border: 1px solid transparent;
  font-size: 11.5px; font-weight: 700; line-height: 1.4; white-space: nowrap;
}
.clm-ar .status-badge.st-submitted { background: #eaf3fa; color: #1f6c9e; border-color: #b9d8ee; }
.clm-ar .status-badge.st-approved  { background: #eaf7ee; color: #1e8449; border-color: #b9e3c6; }
.clm-ar .status-badge.st-pending   { background: #fff4e0; color: #a15a00; border-color: #f6d39a; }
.clm-ar .status-badge.st-sendback  { background: #f3effd; color: #5b3fc4; border-color: #d6cbf8; }
.clm-ar .status-badge.st-rejected  { background: #fdecea; color: #b3261e; border-color: #f5c2bc; }
.clm-ar .status-badge.st-default   { background: #f4f5f7; color: #5a6a7a; border-color: #dde3ea; }
.clm-ar .clm-ar-dev { display: block; width: fit-content; margin: 4px auto 0; background: #fdecea; color: #b3261e; border-color: #f5c2bc; }
.clm-ar .stage-badge { background: #fff; color: #1a1a1a; border-color: #dde3ea; }
.clm-ar .stage-badge i { color: #7f8c9a; margin-right: 2px; }
.clm-ar .seg-badge { border-radius: 4px; }
.clm-ar .seg-badge.seg-cement  { background: #f1f3f7; color: #3a4451; border-color: #dde3ea; }
.clm-ar .seg-badge.seg-rmc     { background: #e6f4ea; color: #2e7d32; border-color: #c4e3cc; }
.clm-ar .seg-badge.seg-bpd     { background: #fdf3e1; color: #a35400; border-color: #f3d9ad; }
.clm-ar .seg-badge.seg-default { background: #f4f5f7; color: #5a6a7a; border-color: #dde3ea; }

/* pagination */
.clm-ar .clm-pagination-bottom {
  display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; padding: 12px 20px;
}
.clm-ar .clm-ar-pageinfo { font-size: 12px; color: #5a6a7a; }
.clm-ar .clm-pagination-controls { display: flex; gap: 4px; flex-wrap: wrap; }
.clm-ar .clm-page-btn {
  min-width: 32px; height: 32px; padding: 0 8px; border: 1px solid #cdd4dc; border-radius: 6px; background: #fff;
  color: #3a4451; font-size: 12.5px; font-weight: 700; display: flex; align-items: center; justify-content: center; cursor: pointer;
}
.clm-ar .clm-page-btn:hover:not(:disabled) { background: #f4f5f7; }
.clm-ar .clm-page-btn.active { background: #1a1a1a; border-color: #1a1a1a; color: #F3D54E; }
.clm-ar .clm-page-btn:disabled { color: #b0b9c4; background: #fafbfc; border-color: #e6eaef; cursor: not-allowed; }

/* ===================== Responsive ===================== */
@media (max-width: 1100px) {
  .clm-ar .clm-ar-stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 768px) {
  .clm-ar { padding: 12px; }
  .clm-ar .clm-ar-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .clm-ar .clm-ar-stat.st-total { grid-column: 1 / -1; }
  .clm-ar .clm-ar-legend { width: 100%; }
  .clm-ar .clm-ar-plot { height: 200px; }
  .clm-ar .clm-ar-chart-body { padding-left: 30px; }
  .clm-ar .clm-ar-xtick.is-skip { visibility: hidden; }
  .clm-ar .clm-ar-xtick.is-current, .clm-ar .clm-ar-xtick.is-hover { visibility: visible; }
  .clm-ar .clm-ar-mtd { display: none; }

  /* table -> label / value cards */
  .clm-ar .clm-table-wrap { max-height: none; border: 0; background: #f4f5f7; padding: 12px; }
  .clm-ar .clm-ar-table thead { display: none; }
  .clm-ar .clm-ar-table, .clm-ar .clm-ar-table tbody, .clm-ar .clm-ar-table tr, .clm-ar .clm-ar-table td { display: block; width: 100%; }
  .clm-ar .clm-ar-table tr { margin-bottom: 12px; background: #fff; border: 1px solid #dde3ea; border-radius: 8px; overflow: hidden; }
  .clm-ar .clm-ar-table td {
    display: flex; justify-content: flex-end; align-items: center; flex-wrap: wrap; gap: 6px 8px; box-sizing: border-box;
    padding: 9px 14px; border: 0 !important; border-bottom: 1px solid #eef1f5 !important;
    text-align: right !important; white-space: normal; max-width: none !important; min-width: 0 !important;
  }
  .clm-ar .clm-ar-table td::before {
    content: attr(data-label); flex-shrink: 0; font-size: 11.5px; font-weight: 700; color: #5a6a7a;
    text-transform: uppercase; letter-spacing: .5px; text-align: left; margin-right: auto;
  }
  .clm-ar .clm-ar-table .clm-ar-dev { margin: 0; }
  .clm-ar .clm-ar-by { white-space: normal; overflow-wrap: anywhere; }
  .clm-ar .clm-ar-table td:first-child { background: #fafbfc; }
  .clm-ar .clm-ar-table td:last-child { border-bottom: 0 !important; }
  .clm-ar .clm-ar-table td.col-customer, .clm-ar .clm-ar-table td.col-submitted-by { display: block; }
  .clm-ar .clm-ar-table td.col-customer::before,
  .clm-ar .clm-ar-table td.col-submitted-by::before { display: block; margin-bottom: 4px; }
  .clm-ar .clm-ar-table td.col-customer, .clm-ar .clm-ar-table td.col-submitted-by { text-align: left !important; }
  .clm-ar .clm-ar-table tr.clm-ar-empty td { display: block; text-align: center !important; }
  .clm-ar .clm-ar-table tr.clm-ar-empty td::before { content: none; }
}

/* ===================== TSH overrides ===================== */
.clm-ar .clm-option-code { margin-left: 4px; font-weight: 400; color: #7f8c9a; }
/* slightly tighter cells so all columns fit at 1366px */
.clm-ar .clm-ar-table { font-size: 12.5px; }
.clm-ar .clm-ar-table th { padding: 10px 7px; font-size: 10.5px; letter-spacing: .4px; }
.clm-ar .clm-ar-table td { padding: 10px 7px; }
.clm-ar .clm-ar-table tr > :first-child { padding-left: 16px; }
.clm-ar .clm-ar-table tr > :last-child  { padding-right: 16px; }
.clm-ar .clm-ar-table td.col-customer { min-width: 120px; max-width: 180px; }
.clm-ar .clm-ar-table td.col-wrap { min-width: 76px; max-width: 120px; }

/* Filter row: 7 -> 4 -> 2 -> 1 (same as master) */
@media (max-width: 1280px) {
  .clm-ar .clm-filter-row { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 768px) {
  .clm-ar .clm-filter-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .clm-ar .clm-filter-row { grid-template-columns: 1fr; }
  .clm-ar .clm-ar-stat-v { font-size: 22px; }
  .clm-ar .clm-search-box { width: 100%; }
}

/* ===================== One font family (keep LAST) ===================== */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family: "Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .fa { font-family: FontAwesome !important; }

sp_widget.script:
/*
  CLM – Approval Requests (TSH / TSM / TSH_BPD dashboard) – Server Script  v2.2-TSH
  Built on the TSH persona script, aligned with MD master v2.2. Persona differences (unchanged):
  - Access via role mapping: TSH -> Cement, TSM -> RMC, TSH_BPD -> BPD (with the user's mapped depots)
  - Segment single select (user's segments only); depots limited to the user's depots for that segment
  - Depot options carry zone / region (read-only Zone / Region filters on the client)
  - Only requests initiated by the current user; approval chain chosen once per segment
  - Approvals counted only since the last (re)submission (u_last_submitted_on)
  v2.2-TSH (aligned to master v2.2)
  - New Business filter (input.filters.business): 'trade' | 'non_trade' | 'key' (default 'trade')
  - BUSINESS_CONFIG: one entry per business with its request table, customer table and an
    "enabled" flag. Only Trade is enabled today (x_birl3_clm_clm_new_credit_request).
    Non-Trade and Key are disabled (greyed out in the UI) until their tables are ready –
    to switch one on later, fill in requestTable / customerTable and set enabled: true
    (and adjust the field names / approval chains if those tables differ).
  - data.businessOptions (value, label, enabled), data.selectedBusiness, data.businessLabel
  - A disabled / unknown business returns empty data with data.businessNotReady = true
    (no request/customer queries run); access is still checked first via the role mapping, and the
    user's Segment list + Period options are returned so the filter card stays usable
  - REQUEST_TABLE / CUSTOMER_TABLE now come from the selected business
  - Each table row carries its business (data.requests[].business)
*/
(function() {

    // ---------------------------------------------------------------------------------
    // BUSINESS CONFIG – which tables to read for each business (Trade / Non-Trade / Key)
    // ---------------------------------------------------------------------------------
    var DEFAULT_BUSINESS = 'trade';
    var BUSINESS_CONFIG = {
        trade: {
            label: 'Trade',
            enabled: true,
            requestTable:  'x_birl3_clm_clm_new_credit_request',
            customerTable: 'x_birl3_clm_clm_customer_master1'
        },
        non_trade: {
            label: 'Non-Trade',
            enabled: false,               // TODO: set true once the Non-Trade request table is ready
            requestTable:  '',            // TODO: Non-Trade request table name
            customerTable: ''             // TODO: customer table used by Non-Trade requests
        },
        key: {
            label: 'Key',
            enabled: false,               // TODO: set true once the Key request table is ready
            requestTable:  '',            // TODO: Key request table name
            customerTable: ''             // TODO: customer table used by Key requests
        }
    };
    var BUSINESS_ORDER = ['trade', 'non_trade', 'key'];

    var PERIOD_OPTIONS = [
        { label: 'All Time (Latest)', value: 'latest' },
        { label: 'This Year', value: 'current_year' },
        { label: 'Last Year', value: 'last_year' }
    ];

    // ===================== CONSTANTS =====================
    var SNAPSHOT_TABLE = 'x_birl3_clm_clm_aging_snapshot';
    var ROLE_MAP_TABLE = 'x_birl3_clm_role_user_mapping';

    var F_STATE          = 'state';
    var F_CUSTOMER_REF   = 'customer';
    var F_REQUESTED_AMT  = 'requested_limit';
    var F_APPROVED_AMT   = 'approved_limit';
    var F_PREV_LIMIT     = 'current_credit_limit';
    var F_SUBMITTED_BY   = 'sys_created_by';
    var F_SUBMITTED_ON   = 'sys_created_on';
    var F_REQ_NUMBER     = 'number';
    var F_DEVIATION      = 'is_deviation';
    var F_LAST_SUBMITTED = 'u_last_submitted_on';

    var F_CUST_SEGMENT  = 'segment';
    var F_CUST_DEPOT    = 'depot';

    var ALLOWED_STATUS_KEYWORDS = ['approv', 'submit', 'reject'];   // Returned / Send-Back no longer used
    var monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

    // TSH / TSM / TSH_BPD  ->  Segment
    var AUTHORIZED_ROLES = ['TSH', 'TSM', 'TSH_BPD'];
    var ROLE_SEGMENT_LABEL = { 'TSH': 'Cement', 'TSM': 'RMC', 'TSH_BPD': 'BPD' };

    function pad(n) { return (n < 10 ? '0' : '') + n; }

    // Empty data block (shared by access denied and business not ready)
    function setEmptyData() {
        data.scorecards = { total: 0, submitted: 0, approved: 0, rejected: 0, deviated: 0 };
        data.chart = { year: new Date().getFullYear(), months: [], monthKeys: [], rangeLabel: '', series: {}, max: 1 };
        data.requests = [];
        data.filterOpts = { depots: [], segments: [], periods: [] };
        data.statusOptions = [];
        data.periodLabel = '';
    }

    function emptyPayload(msg) {
        setEmptyData();
        data.isAuthorized = false;
        data.accessDenied = true;
        data.accessMessage = msg;
    }

    // ===================== 0. BUSINESS SELECTION =====================
    var inputFilters = (typeof input !== 'undefined' && input && input.filters) ? input.filters : {};

// Business options from CLMBusinessAccess (persona TSH); businesses not built yet are not listed
var BUSINESS_BUILT = { trade: true, non_trade: true, key: false };
var access = { trade: false, nonTrade: false, key: false };
try {
    var biz;
    try { biz = new x_birl3_clm.CLMBusinessAccess(); } catch (e0) { biz = new CLMBusinessAccess(); }
    var a = biz.getAccess('TSH') || {};
    access.trade = !!a.trade; access.nonTrade = !!a.nonTrade; access.key = !!a.key;
} catch (e) { gs.error('CLM trade TSH approval requests: CLMBusinessAccess failed - ' + e); }

var allowedBiz = { trade: access.trade, non_trade: access.nonTrade, key: access.key };
data.businessOptions = [];
BUSINESS_ORDER.forEach(function(k) {
    if (allowedBiz[k] && BUSINESS_BUILT[k]) data.businessOptions.push({ value: k, label: BUSINESS_CONFIG[k].label, enabled: true });
});

    var selectedBusiness = (inputFilters.business || DEFAULT_BUSINESS).toString();
    if (!BUSINESS_CONFIG[selectedBusiness]) selectedBusiness = DEFAULT_BUSINESS;
    var bizCfg = BUSINESS_CONFIG[selectedBusiness];

    data.selectedBusiness    = selectedBusiness;
    data.businessLabel       = bizCfg.label;
    data.businessNotReady    = false;
    data.businessNotReadyMsg = '';

    // ===================== 1. ROLE MAPPING (1 query) =====================
    var currentUserId   = gs.getUserID();
    var currentUserName = gs.getUserName();

    var depotSetForUser = {};   // all depots of the user
    var segmentDepotMap = {};   // segmentLabel -> { depot: true }
    var userSegmentSet  = {};

    var grRole = new GlideRecord(ROLE_MAP_TABLE);
    var qcRole = grRole.addQuery('u_user', currentUserId);
    qcRole.addOrCondition('u_user', currentUserName);
    grRole.addQuery('u_role', 'IN', AUTHORIZED_ROLES);
    grRole.query();
    while (grRole.next()) {
        var roleVal  = grRole.getValue('u_role');
        var segLabel = ROLE_SEGMENT_LABEL[roleVal];
        var depotVal = grRole.getValue('u_depot');

        if (depotVal) depotSetForUser[depotVal] = true;
        if (segLabel) {
            userSegmentSet[segLabel] = true;
            if (depotVal) {
                if (!segmentDepotMap[segLabel]) segmentDepotMap[segLabel] = {};
                segmentDepotMap[segLabel][depotVal] = true;
            }
        }
    }

    var userSegmentList = Object.keys(userSegmentSet).sort();
    if (userSegmentList.length === 0) {
        emptyPayload('You are not mapped to the TSH, TSM, or TSH_BPD role. Contact your administrator if you believe this is incorrect.');
        return;
    }
    data.isAuthorized = true;
    data.accessDenied = false;

    // ===================== 2. FILTER INPUT =====================
    function normalizeArray(val) {
        if (typeof val === 'string') {
            try { val = JSON.parse(val); }
            catch (e) { val = val ? [val] : []; }
        }
        if (!Array.isArray(val)) { val = val ? [val] : []; }
        return val;
    }
inputFilters.depots   = normalizeArray(inputFilters.depots);
inputFilters.segments = normalizeArray(inputFilters.segments);
inputFilters.business = selectedBusiness;
data.filters = inputFilters;

// Segments: empty = All Segments the user is mapped to
var reqSegs = inputFilters.segments.length ? inputFilters.segments
            : (inputFilters.segment ? [inputFilters.segment] : []);     // old single value, back-compat
var selectedSegments = reqSegs.filter(function(s) { return userSegmentList.indexOf(s) > -1; });  // never trust the client
if (!selectedSegments.length) selectedSegments = userSegmentList.slice();
data.selectedSegments = selectedSegments;

    // ===================== 2b. BUSINESS NOT READY (Non-Trade / Key) =====================
    // Tables not ready yet -> placeholder, no request/customer queries.
    // Segment list and Period options are kept so the filter card stays usable.
if (selectedBusiness !== DEFAULT_BUSINESS) {
    setEmptyData();
    data.filterOpts.segments = userSegmentList;
    data.filterOpts.periods  = PERIOD_OPTIONS;
    var p = inputFilters.period;
    data.selectedPeriod = (p === 'current_year' || p === 'last_year') ? p : 'latest';
    data.businessNotReady = true;
    data.businessNotReadyMsg = selectedBusiness === 'non_trade'
        ? 'Non-Trade approval requests are shown in the Non-Trade approval requests widget.'
        : 'Approval request details for ' + bizCfg.label + ' customers are not available yet.';
    return;
}

    var REQUEST_TABLE  = bizCfg.requestTable;
    var CUSTOMER_TABLE = bizCfg.customerTable;

    // Depots: only those mapped to the selected segment
// Depots: union of the depots mapped to the selected segments
var depotSetForSegments = {};
selectedSegments.forEach(function(seg) {
    var m = segmentDepotMap[seg] || depotSetForUser;
    Object.keys(m).forEach(function(d) { depotSetForSegments[d] = true; });
});
var userDepotList = Object.keys(depotSetForSegments).sort();
    // Selected depots (validated against the segment's depots)
    var selectedDepots = inputFilters.depots.filter(function(d) { return userDepotList.indexOf(d) > -1; });
    if (selectedDepots.length === 0) selectedDepots = userDepotList;

    var statusFilter = inputFilters.status || '';

    // ===================== 3. DEPOT NAMES + SEGMENT RAW VALUE =====================
    var depotMap = {};
    var depotNameMap = {};
var segRawMap = {};      // lower-case segment label -> raw stored value
var selectedSegmentRaws = selectedSegments.slice();

    if (userDepotList.length > 0) {
        // depot code -> depot name + zone/region (one grouped query, only user's depots)
        var ZONE_CODE_FIELD   = 'zone';
        var ZONE_NAME_FIELD   = 'zone_name';
        var REGION_CODE_FIELD = 'region';
        var REGION_NAME_FIELD = 'region_name';

        var probe = new GlideRecord(CUSTOMER_TABLE);
        var hasZoneCode   = probe.isValidField(ZONE_CODE_FIELD);
        var hasZoneName   = probe.isValidField(ZONE_NAME_FIELD);
        var hasRegionCode = probe.isValidField(REGION_CODE_FIELD);
        var hasRegionName = probe.isValidField(REGION_NAME_FIELD);

        var gaDepot = new GlideAggregate(CUSTOMER_TABLE);
        gaDepot.addQuery(F_CUST_DEPOT, 'IN', userDepotList);
        gaDepot.addAggregate('COUNT');
        gaDepot.groupBy(F_CUST_DEPOT);
        gaDepot.groupBy('depot_name');
        if (hasZoneCode)   gaDepot.groupBy(ZONE_CODE_FIELD);
        if (hasZoneName)   gaDepot.groupBy(ZONE_NAME_FIELD);
        if (hasRegionCode) gaDepot.groupBy(REGION_CODE_FIELD);
        if (hasRegionName) gaDepot.groupBy(REGION_NAME_FIELD);
        gaDepot.query();

        while (gaDepot.next()) {
            var dCode = String(gaDepot.getValue(F_CUST_DEPOT) || '').trim();
            if (!dCode) continue;

            var zCode = hasZoneCode   ? (gaDepot.getDisplayValue(ZONE_CODE_FIELD)   || gaDepot.getValue(ZONE_CODE_FIELD)   || '') : '';
            var zName = hasZoneName   ? (gaDepot.getDisplayValue(ZONE_NAME_FIELD)   || gaDepot.getValue(ZONE_NAME_FIELD)   || '') : '';
            var rCode = hasRegionCode ? (gaDepot.getDisplayValue(REGION_CODE_FIELD) || gaDepot.getValue(REGION_CODE_FIELD) || '') : '';
            var rName = hasRegionName ? (gaDepot.getDisplayValue(REGION_NAME_FIELD) || gaDepot.getValue(REGION_NAME_FIELD) || '') : '';

            if (!depotMap[dCode]) {
                depotMap[dCode] = {
                    label: String(gaDepot.getValue('depot_name') || dCode).trim(),
                    value: dCode,
                    zoneCode: zCode, zoneName: zName,
                    regionCode: rCode, regionName: rName
                };
            } else {
                var dm = depotMap[dCode];
                if (!dm.zoneCode && zCode) dm.zoneCode = zCode;
                if (!dm.zoneName && zName) dm.zoneName = zName;
                if (!dm.regionCode && rCode) dm.regionCode = rCode;
                if (!dm.regionName && rName) dm.regionName = rName;
            }
        }

        // populate original depotNameMap for later script usage
        for (var key in depotMap) { depotNameMap[key] = depotMap[key].label; }

        // segment display label -> raw stored value (scoped to user's depots)
        var gaSeg = new GlideAggregate(CUSTOMER_TABLE);
        gaSeg.addQuery(F_CUST_DEPOT, 'IN', userDepotList);
        gaSeg.addAggregate('COUNT');
        gaSeg.groupBy(F_CUST_SEGMENT);
        gaSeg.query();
while (gaSeg.next()) {
    var rawSeg  = gaSeg.getValue(F_CUST_SEGMENT) || '';
    var dispSeg = gaSeg.getDisplayValue(F_CUST_SEGMENT) || '';
    if (rawSeg)  segRawMap[rawSeg.toLowerCase()]  = rawSeg;
    if (dispSeg) segRawMap[dispSeg.toLowerCase()] = rawSeg;
}
selectedSegmentRaws = selectedSegments.map(function(s) { return segRawMap[s.toLowerCase()] || s; });
    }

    var depotFilterOpts = userDepotList.map(function(d) {
        return depotMap[d] || { value: d, label: depotNameMap[d] || d };
    });
    depotFilterOpts.sort(function(a, b) { return String(a.label).localeCompare(String(b.label)); });

    data.filterOpts = {
        depots: depotFilterOpts,
        segments: userSegmentList,
        periods: PERIOD_OPTIONS
    };

    // ===================== 4. PERIOD =====================
    function buildPeriodRange(periodStr) {
        var nowStr = new GlideDateTime().getValue();
        var curYear  = parseInt(nowStr.substr(0, 4), 10);
        var curMonth = parseInt(nowStr.substr(5, 2), 10);
        var curDay   = parseInt(nowStr.substr(8, 2), 10);
        var startGdt = new GlideDateTime();
        var endGdt   = new GlideDateTime();
        var label = '';
        var value = periodStr || 'latest';

        if (value === 'current_year') {
            startGdt.setValue(curYear + '-01-01 00:00:00');
            endGdt.setValue(nowStr);
            label = 'Jan 1 – ' + monthNames[curMonth - 1] + ' ' + curDay + ', ' + curYear;
        } else if (value === 'last_year') {
            var lastYear = curYear - 1;
            startGdt.setValue(lastYear + '-01-01 00:00:00');
            endGdt.setValue(lastYear + '-12-31 23:59:59');
            label = 'Jan 1 – Dec 31, ' + lastYear;
        } else {
            startGdt.setValue('1990-01-01 00:00:00');
            endGdt.setValue(nowStr);
            label = 'All Time (Latest)';
            value = 'latest';
        }
        return { start: startGdt, end: endGdt, label: label, value: value };
    }

    var range = buildPeriodRange(inputFilters.period || 'latest');
    data.periodLabel    = range.label;
    data.selectedPeriod = range.value;

    // ===================== 5. COMMON FILTER (depot + initiator + segment) =====================
    function applyAppFilters(gr) {
        gr.addQuery('customer.' + F_CUST_DEPOT, 'IN', selectedDepots.length > 0 ? selectedDepots : ['none']);

        var qcInit = gr.addQuery('initiator', currentUserId);
        qcInit.addOrCondition('initiator', currentUserName);

        gr.addQuery('customer.' + F_CUST_SEGMENT, 'IN', selectedSegmentRaws);
    }

    // ===================== 6. APPROVAL CHAINS =====================
    var CEMENT_CHAIN = [
      { label: 'TSH',     field: 'u_approver_tsh'     },
      { label: 'RHM',     field: 'u_approver_rhm'     },
      { label: 'ZHM',     field: 'u_approver_zhm'     },
      { label: 'ZCH',     field: 'u_approver_zch'     },
      { label: 'HO',      field: 'u_approver_ho'      },
      { label: 'NSH',     field: 'u_approver_nsh'     },
      { label: 'NSH CCH', field: 'u_approver_nsh_cch' },
      { label: 'CMO',     field: 'u_approver_cmo'     },
      { label: 'CMO CFO', field: 'u_approver_cmo_cfo' },
      { label: 'MD',      field: 'u_approver_md'      }
    ];
    var RMC_CHAIN = [
      { label: 'TSM',          field: 'u_approver_tsm'             },
      { label: 'RH CH RMC',    field: 'u_approver_rh_ch_rmc'       },
      { label: 'ZH RMC',       field: 'u_approver_zh_rmc'          },
      { label: 'ZCH',          field: 'u_approver_zch'             },
      { label: 'HO',           field: 'u_approver_ho'              },
      { label: 'HEAD RMC',     field: 'u_approver_head_rmc'        },
      { label: 'HEAD KEY CH',  field: 'u_approver_head_key_ch_rmc' },
      { label: 'HEAD KEY CCH', field: 'u_approver_head_key_cch'    },
      { label: 'BH',           field: 'u_approver_bh'              },
      { label: 'BH CFO',       field: 'u_approver_bh_cfo'          },
      { label: 'MD',           field: 'u_approver_md'              }
    ];
    var BPD_CHAIN = [
      { label: 'TSH BPD',  field: 'u_approver_tsh_bpd'  },
      { label: 'ZH BPD',   field: 'u_approver_zh_bpd'   },
      { label: 'HSBPD',    field: 'u_approver_hsbpd'    },
      { label: 'ZCH',      field: 'u_approver_zch'      },
      { label: 'HO',       field: 'u_approver_ho'       },
      { label: 'HBPD',     field: 'u_approver_hbpd'     },
      { label: 'CCH HBPD', field: 'u_approver_cch_hbpd' },
      { label: 'BH',       field: 'u_approver_bh'       },
      { label: 'CFO',      field: 'u_approver_cfo'      },
      { label: 'MD',       field: 'u_approver_md'       }
    ];
    // All rows belong to ONE segment (filter is single-select), so the chain is chosen once
    function chainFor(seg) {
    var s = String(seg || '').toLowerCase();
    if (s.indexOf('rmc') > -1) return RMC_CHAIN;
    if (s.indexOf('bpd') > -1) return BPD_CHAIN;
    return CEMENT_CHAIN;
}

    // ===================== 7. HELPERS =====================
    function getFilteredStatusOptions(table, field) {
        var arr = [], seen = {};
        var gr = new GlideRecord('sys_choice');
        gr.addQuery('name', table);
        gr.addQuery('element', field);
        gr.addQuery('inactive', false);
        gr.orderBy('sequence');
        gr.query();
        while (gr.next()) {
            var v = gr.getValue('value');
            var lbl = gr.getValue('label') || '';
            if (!v || seen[v]) continue;
            var lower = lbl.toLowerCase();
            if (!ALLOWED_STATUS_KEYWORDS.some(function(kw) { return lower.indexOf(kw) > -1; })) continue;
            seen[v] = true;
            arr.push({ value: v, label: lbl });
        }
        return arr;
    }

    // Amount display in Indian units, picked by size:
    //   < 1,000            -> ₹950
    //   1,000 - 99,999     -> ₹1.5K
    //   1,00,000 - 99,99,999 -> ₹12.5L
    //   >= 1,00,00,000     -> ₹2.5Cr
    function formatAmt(v) {
        if (v === undefined || v === null || v === '') return '';
        var n = parseFloat(v);
        if (isNaN(n)) return v;

        var sign = n < 0 ? '-' : '';
        var a = Math.abs(n);
        var val, unit;

        if (a >= 10000000)      { val = a / 10000000; unit = 'Cr'; }
        else if (a >= 100000)   { val = a / 100000;   unit = 'L';  }
        else if (a >= 1000)     { val = a / 1000;     unit = 'K';  }
        else                    { val = a;            unit = '';   }

        // up to 2 decimals, trailing zeros removed (1.50 -> 1.5, 2.00 -> 2)
        var txt = String(parseFloat(val.toFixed(2)));
        return sign + '\u20B9' + txt + unit;
    }
	// Resolve sys_created_by (user name / email) to the user's full name
function buildUserNameMap(userNames) {
    var map = {}, list = [], seen = {};
    userNames.forEach(function(u) {
        u = String(u || '').trim();
        if (u && !seen[u.toLowerCase()]) { seen[u.toLowerCase()] = true; list.push(u); }
    });
    if (!list.length) return map;
    var ug = new GlideRecord('sys_user');
    var qu = ug.addQuery('user_name', 'IN', list.join(','));
    qu.addOrCondition('email', 'IN', list.join(','));
    ug.query();
    while (ug.next()) {
        var full = ug.getValue('name') || '';
        if (!full) continue;
        map[String(ug.getValue('user_name') || '').toLowerCase()] = full;
        map[String(ug.getValue('email') || '').toLowerCase()] = full;
    }
    return map;
}
function nameFromMap(map, raw) {
    raw = String(raw || '').trim();
    return map[raw.toLowerCase()] || raw;
}

    data.statusOptions = getFilteredStatusOptions(REQUEST_TABLE, F_STATE);

    // Only Pending (submitted) / Approved / Rejected requests are in scope
    var allowedStateValues = data.statusOptions.map(function(o) { return o.value; });
    function applyStateScope(gr) {
        if (allowedStateValues.length > 0) gr.addQuery(F_STATE, 'IN', allowedStateValues);
    }

    // ===================== 8. SCORECARDS (1 aggregate + 1 deviation aggregate) =====================
    data.scorecards = { total: 0, submitted: 0, approved: 0, rejected: 0, deviated: 0 };

    var agg = new GlideAggregate(REQUEST_TABLE);
    agg.addAggregate('COUNT', F_STATE);
    agg.groupBy(F_STATE);
    agg.addQuery(F_SUBMITTED_ON, '>=', range.start);
    agg.addQuery(F_SUBMITTED_ON, '<=', range.end);
    applyAppFilters(agg);
    applyStateScope(agg);
    agg.query();
    while (agg.next()) {
        var st  = (agg.getValue(F_STATE) || '').toLowerCase();
        var cnt = parseInt(agg.getAggregate('COUNT', F_STATE), 10) || 0;
        if (st.indexOf('submit') > -1)      data.scorecards.submitted += cnt;
        else if (st.indexOf('approv') > -1) data.scorecards.approved  += cnt;
        else if (st.indexOf('reject') > -1) data.scorecards.rejected  += cnt;
    }
    data.scorecards.total = data.scorecards.submitted + data.scorecards.approved + data.scorecards.rejected;

    var devGr = new GlideAggregate(REQUEST_TABLE);
    devGr.addQuery(F_DEVIATION, true);
    devGr.addQuery(F_SUBMITTED_ON, '>=', range.start);
    devGr.addQuery(F_SUBMITTED_ON, '<=', range.end);
    devGr.addAggregate('COUNT');
    applyAppFilters(devGr);
    applyStateScope(devGr);
    devGr.query();
    if (devGr.next()) {
        data.scorecards.deviated = parseInt(devGr.getAggregate('COUNT'), 10) || 0;
    }

    // ---------------------------------------------------------------------------------
    // 9. CHART: rolling 12 months = 11 previous months + current month to date (1 query)
    // Months are computed in the user's time zone (getDisplayValueInternal).
    // ---------------------------------------------------------------------------------
    var nowLocalStr   = new GlideDateTime().getDisplayValueInternal();   // 'yyyy-MM-dd HH:mm:ss' (user TZ)
    var curChartYear  = parseInt(nowLocalStr.substr(0, 4), 10);
    var curChartMonth = parseInt(nowLocalStr.substr(5, 2), 10);        // 1..12

    var monthKeys = [];          // 'yyyy-MM'
    var monthLabels = [];        // "Nov '25"
    var monthIndex = {};         // 'yyyy-MM' -> 0..11
    var series = { total: [], submitted: [], approved: [], rejected: [] };

    for (var back = 11; back >= 0; back--) {
        var cy = curChartYear;
        var cm = curChartMonth - back;
        while (cm < 1) { cm += 12; cy--; }
        var mKey = cy + '-' + pad(cm);
        monthIndex[mKey] = monthKeys.length;
        monthKeys.push(mKey);
        monthLabels.push(monthNames[cm - 1] + " '" + String(cy).substr(2));
        series.total.push(0);
        series.submitted.push(0);
        series.approved.push(0);
        series.rejected.push(0);
    }

    var chartStartGdt = new GlideDateTime();
    chartStartGdt.setDisplayValueInternal(monthKeys[0] + '-01 00:00:00');  // 1st of first month, user TZ
    var chartEndGdt = new GlideDateTime();                                  // now

    var grChart = new GlideRecord(REQUEST_TABLE);
    grChart.addQuery(F_SUBMITTED_ON, '>=', chartStartGdt);
    grChart.addQuery(F_SUBMITTED_ON, '<=', chartEndGdt);
    applyAppFilters(grChart);
    applyStateScope(grChart);
    grChart.query();
    while (grChart.next()) {
        var subOnUtc = grChart.getValue(F_SUBMITTED_ON);
        if (!subOnUtc) continue;
        var subOnLocal = new GlideDateTime(subOnUtc).getDisplayValueInternal();
        var mth = monthIndex[subOnLocal.substr(0, 7)];
        if (typeof mth === 'undefined') continue;

        var sState = (grChart.getValue(F_STATE) || '').toLowerCase();
        var counted = true;
        if (sState.indexOf('submit') > -1)      series.submitted[mth]++;
        else if (sState.indexOf('approv') > -1) series.approved[mth]++;
        else if (sState.indexOf('reject') > -1) series.rejected[mth]++;
        else counted = false;
        if (counted) series.total[mth]++;
    }

    var maxVal = 1;
    Object.keys(series).forEach(function(k) {
        for (var i = 0; i < series[k].length; i++) if (series[k][i] > maxVal) maxVal = series[k][i];
    });

    var firstKeyParts = monthKeys[0].split('-');
    data.chart = {
        year: curChartYear,
        monthKeys: monthKeys,
        months: monthLabels,
        rangeLabel: monthNames[parseInt(firstKeyParts[1], 10) - 1] + ' ' + firstKeyParts[0] +
                    ' – ' + monthNames[curChartMonth - 1] + ' ' + curChartYear + ' (month to date)',
        series: series,
        max: maxVal
    };

    // ===================== 10. TABLE (single pass + bulk maps) =====================
    data.requests = [];

    var rows = [];            // output rows
    var rowMeta = [];         // parallel array: { reqId, chainIds[], custId }
    var reqIds = [];
	  var chainIds = [];
	  var rowChain = [];
    var lastSubmittedMap = {};
    var custIds = [];
    var custCache = {};       // dot-walk each customer only once

    var reqGr = new GlideRecord(REQUEST_TABLE);
    if (statusFilter) reqGr.addQuery(F_STATE, statusFilter);
    reqGr.addQuery(F_SUBMITTED_ON, '>=', range.start);
    reqGr.addQuery(F_SUBMITTED_ON, '<=', range.end);
    applyAppFilters(reqGr);
    applyStateScope(reqGr);
    reqGr.orderByDesc(F_SUBMITTED_ON);
    reqGr.setLimit(500);
    reqGr.query();

    while (reqGr.next()) {
        var reqSysId = reqGr.getUniqueValue();
        var custSysId = reqGr.getValue(F_CUSTOMER_REF) || '';

        reqIds.push(reqSysId);
        lastSubmittedMap[reqSysId] = reqGr.getValue(F_LAST_SUBMITTED) || '';

        if (custSysId && !custCache[custSysId]) {
            custIds.push(custSysId);
            var depotCode = reqGr.getElement('customer.depot').toString() || '';
            var dMapInfo = depotMap[depotCode] || {};
            var zName = dMapInfo.zoneName || reqGr.getElement('customer.zone_name').toString() || '';
            var zCode = dMapInfo.zoneCode || reqGr.getElement('customer.zone').toString() || '';
            var rName = dMapInfo.regionName || reqGr.getElement('customer.region_name').toString() || '';
            var rCode = dMapInfo.regionCode || reqGr.getElement('customer.region').toString() || '';
            var dName = dMapInfo.label || reqGr.getElement('customer.depot_name').toString() || depotCode;
            function fmt(n, c) { if(n && c && n !== c) return n + ' (' + c + ')'; return n || c || ''; }

            custCache[custSysId] = {
                code:    reqGr.getElement('customer.customer_code_sap').toString() || '',
                name:    reqGr.getElement('customer.customer_name').toString() || reqGr.getDisplayValue(F_CUSTOMER_REF),
                pan:     reqGr.getElement('customer.pan').toString() || '',
                segment: reqGr.getElement('customer.segment').getDisplayValue() || '',
                zone:    fmt(zName, zCode),
                zoneName: zName, zoneCode: zCode,
                region:  fmt(rName, rCode),
                regionName: rName, regionCode: rCode,
                depot:   fmt(dName, depotCode),
                depotName: dName, depotCode: depotCode
            };
        }
        var cu = custCache[custSysId] || { code: '', name: reqGr.getDisplayValue(F_CUSTOMER_REF), pan: '', segment: '', zone: '', region: '', depot: '' };

        // approver ids (raw sys_ids only - no display lookups per row)
// approver ids (raw sys_ids only) using THIS row's segment chain
rowMeta.push({ reqId: reqSysId, custId: custSysId });
        var statVal   = reqGr.getValue(F_STATE);
        var statLabel = reqGr.getDisplayValue(F_STATE);
        if ((statVal || '').toLowerCase().indexOf('submit') > -1) statLabel = 'Pending';

        var devVal = reqGr.getValue(F_DEVIATION);

        rows.push({
            business:     selectedBusiness,
            requestCode:  reqGr.getDisplayValue(F_REQ_NUMBER) || reqSysId,
            customerCode: cu.code,
            customerName: cu.name,
            pan:          cu.pan,
            segment:      cu.segment,
            zone:         cu.zone,
            region:       cu.region,
            depot:        cu.depot,
            zoneName:     cu.zoneName,   zoneCode:   cu.zoneCode,
            regionName:   cu.regionName, regionCode: cu.regionCode,
            depotName:    cu.depotName,  depotCode:  cu.depotCode,
            status:       statVal,
            statusLabel:  statLabel,
            isDeviation:  (devVal == '1' || devVal == 'true'),
            stage:        '',
            submittedBy:  '',
submittedByRaw: reqGr.getValue(F_SUBMITTED_BY),
            submittedOn:  reqGr.getDisplayValue(F_SUBMITTED_ON),
            prevLimit:    formatAmt(reqGr.getValue(F_PREV_LIMIT)),
            requested:    formatAmt(reqGr.getValue(F_REQUESTED_AMT)),
            approved:     formatAmt(reqGr.getValue(F_APPROVED_AMT)),
            outstanding:  ''
        });
    }

    if (rows.length === 0) return;

// ---- Pending approvers: ONE query, only state = requested ----
// ---- Pending approvers: state = requested (same as RHM) ----
var pendingMap = {};   // request sys_id -> [approver names]
var appGr = new GlideRecord('sysapproval_approver');
var qcApp = appGr.addQuery('sysapproval', 'IN', reqIds);
qcApp.addOrCondition('document_id', 'IN', reqIds);
appGr.addQuery('state', 'requested');
appGr.orderBy('sys_created_on');
appGr.query();
while (appGr.next()) {
    var aReqId = appGr.getValue('sysapproval') || appGr.getValue('document_id');
    if (!aReqId) continue;
    var aName = appGr.getDisplayValue('approver') || appGr.getDisplayValue('group') || '';
    if (!aName) continue;
    var plist = pendingMap[aReqId] = pendingMap[aReqId] || [];
    if (plist.indexOf(aName) === -1) plist.push(aName);
}

var userNameMap = buildUserNameMap(rows.map(function(r) { return r.submittedByRaw; }));
    // ---- Latest outstanding per customer: ONE query, only listed customers ----
    var snapshotMap = {};
    if (custIds.length > 0) {
        var snapGr = new GlideRecord(SNAPSHOT_TABLE);
        snapGr.addQuery('customer', 'IN', custIds);
        snapGr.orderByDesc('sys_created_on');
        snapGr.query();
        while (snapGr.next()) {
            var sc = snapGr.getValue('customer');
            if (typeof snapshotMap[sc] === 'undefined') {
                snapshotMap[sc] = snapGr.getValue('total_outstanding');
            }
        }
    }

    // ---- Final assembly ----
for (var fi = 0; fi < rows.length; fi++) {
    var isPendingRow = String(rows[fi].status || '').toLowerCase().indexOf('submit') > -1;
    rows[fi].stage = isPendingRow ? (pendingMap[rowMeta[fi].reqId] || []).join(', ') : '';
    rows[fi].outstanding = formatAmt(snapshotMap[rowMeta[fi].custId]);
    rows[fi].submittedBy = nameFromMap(userNameMap, rows[fi].submittedByRaw);
    delete rows[fi].submittedByRaw;
}
    data.requests = rows;

})();
